<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="form-card"><p class="eyebrow">Transaction</p><h1>Record Sale</h1><?php $errors=session()->getFlashdata('errors')??[]; if($errors): ?><div class="alert error"><ul><?php foreach($errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form action="<?= site_url('sales') ?>" method="post"><?= csrf_field() ?><label>Product *</label><select name="product_id" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= old('product_id')==$p['id']?'selected':'' ?>><?= esc($p['name']) ?> — ₱<?= number_format((float)$p['price'],2) ?> (<?= $p['stock_quantity'] ?> in stock)</option><?php endforeach; ?></select><label>Customer (optional)</label><select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= old('customer_id')==$c['id']?'selected':'' ?>><?= esc($c['full_name']) ?></option><?php endforeach; ?></select><label>Quantity *</label><input type="number" name="quantity" min="1" value="<?= esc(old('quantity',1)) ?>" required><div class="form-actions"><button class="button">Complete Sale</button><a class="button secondary" href="<?= site_url('sales') ?>">Cancel</a></div></form></div><?= $this->endSection() ?>
